      "svg": "<svg viewBox='0 0 1100 1100'><rect x='0' y='0' width='1100' height='1100' fill='#1a1a2e'/><text x='550' y='55' text-anchor='middle' fill='#ffd700' font-weight='bold' font-size='34'>INTENTIONAL CHANGE</text><text x='550' y='95' text-anchor='middle' fill='#888' font-size='20'>Five discoveries, one cycle</text><circle cx='550' cy='290' r='95' fill='#6366f1' fill-opacity='0.2' stroke='#6366f1' stroke-width='3'/><text x='550' y='298' text-anchor='middle' fill='#ffffff' font-weight='bold' font-size='20'>ADULT GROWTH</text><text x='550' y='325' text-anchor='middle' fill='#888' font-size='13'>not a straight line</text><rect x='100' y='450' width='460' height='170' rx='16' fill='#ef4444' fill-opacity='0.12' stroke='#ef4444' stroke-width='2'/><text x='330' y='505' text-anchor='middle' fill='#ef4444' font-weight='bold' font-size='20'>WEEK 1-2</text><text x='330' y='545' text-anchor='middle' fill='#ffffff' font-size='16'>Highly motivated</text><rect x='580' y='450' width='460' height='170' rx='16' fill='#f59e0b' fill-opacity='0.12' stroke='#f59e0b' stroke-width='2'/><text x='810' y='505' text-anchor='middle' fill='#f59e0b' font-weight='bold' font-size='20'>WEEK 3</text><text x='810' y='545' text-anchor='middle' fill='#ffffff' font-size='16'>Resolve fades fast</text><rect x='100' y='650' width='460' height='170' rx='16' fill='#8b5cf6' fill-opacity='0.12' stroke='#8b5cf6' stroke-width='2'/><text x='330' y='705' text-anchor='middle' fill='#8b5cf6' font-weight='bold' font-size='20'>MISSING PIECE</text><text x='330' y='745' text-anchor='middle' fill='#ffffff' font-size='16'>Only 1 of 5 discoveries</text><rect x='580' y='650' width='460' height='170' rx='16' fill='#10b981' fill-opacity='0.12' stroke='#10b981' stroke-width='2'/><text x='810' y='705' text-anchor='middle' fill='#10b981' font-weight='bold' font-size='20'>ICT MODEL</text><text x='810' y='745' text-anchor='middle' fill='#ffffff' font-size='16'>A repeating 5-part cycle</text><rect x='150' y='860' width='800' height='90' rx='16' fill='#ffd700' fill-opacity='0.1' stroke='#ffd700' stroke-width='2'/><text x='550' y='912' text-anchor='middle' fill='#ffd700' font-size='18'>Reading about change is not the same as rewiring it</text></svg>",
